/**
 * Photography registry. Files are generated by scripts/build-images.sh.
 * Current photos are licensed stock (Unsplash Licence) used as placeholders
 * for mood and context only — they do not depict 8PAHAR projects. Replace
 * with commissioned project photography when available (see CREDITS.md).
 */
export interface ImageSource {
  name: string;
  widths: number[];
  /** Intrinsic aspect ratio (width / height) used to reserve layout space. */
  width: number;
  height: number;
}

const img = (name: string, widths: number[], width: number, height: number): ImageSource => ({ name, widths, width, height });

